
/**
 * Na ponta do lápis — Escola de contabilidade
  * Autor: Luan Lima de Queiroz · Aluno da UNINASSAU
   * JavaScript do caderno gamificado (abre no navegador, sem Node.js).
    */

    const SAVE_KEY = "npl-caderno-v1";

    const NPCS = [
      { name: "Ana Figueiredo", xp: 420, turma: "3º período" },
        { name: "Bruno Nogueira", xp: 310, turma: "3º período" },
          { name: "Camila Reis", xp: 180, turma: "3º período" },
          ];

          const MISSOES = [
            {
                id: "conceitos",
                    titulo: "O que a contabilidade registra",
                        tipo: "quiz",
                            itens: [
                                  {
                                          p: "Qual é o objetivo principal da contabilidade?",
                                                  o: [
                                                            "Registrar apenas o dinheiro em caixa",
                                                                      "Fornecer informações úteis sobre o patrimônio e o resultado da entidade",
                                                                                "Calcular impostos no lugar da Receita Federal",
                                                                                          "Substituir o administrador nas decisões do dia a dia",
                                                                                                  ],
                                                                                                          c: 1,
                                                                                                                  e: "A contabilidade produz informação econômica e financeira para usuários internos e externos.",
                                                                                                                        },
                                                                                                                              {
                                                                                                                                      p: "O princípio da entidade determina que:",
                                                                                                                                              o: [
                                                                                                                                                        "O patrimônio da empresa se mistura com o do sócio",
                                                                                                                                                                  "O patrimônio da entidade não se confunde com o dos sócios",
                                                                                                                                                                            "Só pessoas jurídicas podem ter contabilidade",
                                                                                                                                                                                      "Toda empresa precisa de um contador no quadro societário",
                                                                                                                                                                                              ],
                                                                                                                                                                                                      c: 1,
                                                                                                                                                                                                              e: "A empresa é um patrimônio distinto. Dinheiro pessoal do sócio não entra no balanço, salvo integralização formal.",
                                                                                                                                                                                                                    },
                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                  p: "Ativo, passivo e patrimônio líquido formam:",
                                                                                                                                                                                                                                          o: [
                                                                                                                                                                                                                                                    "A Demonstração do Resultado do Exercício",
                                                                                                                                                                                                                                                              "O fluxo de caixa operacional",
                                                                                                                                                                                                                                                                        "A equação patrimonial, base do Balanço Patrimonial",
                                                                                                                                                                                                                                                                                  "O plano de contas de resultado",
                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                  c: 2,
                                                                                                                                                                                                                                                                                                          e: "Ativo = Passivo + Patrimônio Líquido. É a identidade do Balanço Patrimonial.",
                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                            id: "naturezas",
                                                                                                                                                                                                                                                                                                                                titulo: "Natureza das contas",
                                                                                                                                                                                                                                                                                                                                    tipo: "classificar",
                                                                                                                                                                                                                                                                                                                                        itens: [
                                                                                                                                                                                                                                                                                                                                              { n: "Caixa", c: "Ativo" },
                                                                                                                                                                                                                                                                                                                                                    { n: "Fornecedores", c: "Passivo" },
                                                                                                                                                                                                                                                                                                                                                          { n: "Capital Social", c: "Patrimônio Líquido" },
                                                                                                                                                                                                                                                                                                                                                                { n: "Receita de Vendas", c: "Receita" },
                                                                                                                                                                                                                                                                                                                                                                      { n: "Despesas com Aluguel", c: "Despesa" },
                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                  id: "equacao",
                                                                                                                                                                                                                                                                                                                                                                                      titulo: "A equação patrimonial",
                                                                                                                                                                                                                                                                                                                                                                                          tipo: "equacao",
                                                                                                                                                                                                                                                                                                                                                                                              itens: [
                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                            p: "Ativo = R$ 40.000 · Passivo = R$ 15.000. Qual o PL?",
                                                                                                                                                                                                                                                                                                                                                                                                                    o: [15000, 25000, 55000, 40000],
                                                                                                                                                                                                                                                                                                                                                                                                                            c: 25000,
                                                                                                                                                                                                                                                                                                                                                                                                                                    e: "PL = Ativo − Passivo = 25.000.",
                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        p: "Passivo = R$ 22.000 · PL = R$ 18.000. Qual o Ativo?",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                o: [4000, 18000, 22000, 40000],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        c: 40000,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                e: "Ativo = Passivo + PL = 40.000.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const NATS = ["Ativo", "Passivo", "Patrimônio Líquido", "Receita", "Despesa"];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function load() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return JSON.parse(localStorage.getItem(SAVE_KEY) || "null") || defaults();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return defaults();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function defaults() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return { nome: "", turma: "3º período", xp: 0, stars: {}, answered: 0, correct: 0 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function save(s) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              localStorage.setItem(SAVE_KEY, JSON.stringify(s));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let state = load();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let jogo = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const $ = (id) => document.getElementById(id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function show(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelectorAll("section[id^='view-']").forEach((el) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    el.classList.toggle("hidden", el.id !== "view-" + id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".nav a").forEach((a) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            a.classList.toggle("on", a.getAttribute("data-go") === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (id === "caderno") renderCaderno();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (id === "trilha") renderTrilha();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (id === "ranking") renderRank();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function brl(n) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function renderCaderno() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $("ficha").textContent = state.nome + " · " + state.turma + " · UNINASSAU";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $("saudacao").textContent = "Bom retorno, " + state.nome.split(" ")[0] + ".";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const done = Object.keys(state.stars).length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $("resumo").textContent = done + " de " + MISSOES.length + " missões neste caderno.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("xp").textContent = String(state.xp);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $("miss").textContent = done + "/" + MISSOES.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $("prec").textContent = state.answered
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? Math.round((state.correct / state.answered) * 100) + "%"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "—";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function unlocked(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const i = MISSOES.findIndex((m) => m.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (i <= 0) return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (state.stars[MISSOES[i - 1].id] || 0) >= 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function renderTrilha() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $("lista-trilha").innerHTML = MISSOES.map((m, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const open = unlocked(m.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const st = state.stars[m.id] || 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<div class="stat" style="margin-bottom:10px">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "<p class='kicker'>Missão " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (i + 1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (st ? " · " + st + " estrela(s)" : "") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "</p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "<h3>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          m.titulo +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "</h3>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (open
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? '<div class="row"><button class="btn" data-play="' + m.id + '">Abrir</button></div>'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : "<p class='lede'>Conclua a missão anterior para destravar.</p>") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "</div>"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }).join("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function renderRank() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const rows = NPCS.concat([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { name: state.nome || "Você", xp: state.xp, turma: state.turma, you: true },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]).sort((a, b) => b.xp - a.xp);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $("lista-rank").innerHTML = rows
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .map(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (r, i) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '<li class="' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (r.you ? "you" : "") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '"><b>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (i + 1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "º</b><span>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      r.name +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (r.you ? " (você)" : "") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "<br><small>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              r.turma +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "</small></span><span>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              r.xp +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      " XP</span></li>",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .join("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function start(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const m = MISSOES.find((x) => x.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!m || !unlocked(id)) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    jogo = { m, i: 0, acertos: 0, pick: null };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      show("jogo");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderJogo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function renderJogo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const { m, i, acertos } = jogo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const item = m.itens[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $("jogo-kicker").textContent = "Missão · " + (i + 1) + " de " + m.itens.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("jogo-titulo").textContent = m.titulo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $("jogo-status").textContent = acertos + " acerto(s)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const area = $("jogo-area");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (m.tipo === "quiz" || m.tipo === "equacao") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const opts = m.tipo === "equacao" ? item.o.map(brl) : item.o;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const correctVal = m.tipo === "equacao" ? brl(item.c) : item.o[item.c];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  area.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "<p><strong>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              item.p +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "</strong></p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          opts.map((t) => '<button class="opt" data-opt="' + encodeURIComponent(t) + '">' + t + "</button>").join("") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '<div id="exp" class="explain hidden"></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    area.querySelectorAll("[data-opt]").forEach((btn) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          btn.onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (jogo.pick !== null) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const t = decodeURIComponent(btn.getAttribute("data-opt"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  jogo.pick = t;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const ok = t === correctVal;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (ok) jogo.acertos++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          area.querySelectorAll(".opt").forEach((b) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    b.disabled = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (decodeURIComponent(b.getAttribute("data-opt")) === correctVal) b.classList.add("ok");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!ok) btn.classList.add("bad");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const exp = $("exp");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              exp.classList.remove("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      exp.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "<p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (ok ? "Resposta correta." : "Revise.") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    " " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              item.e +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "</p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<div class="row"><button class="btn" id="prox">Próxima</button></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $("prox").onclick = nextItem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            area.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "<p class='kicker'>Classifique a conta</p><h3>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item.n +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "</h3>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            NATS.map((n) => '<button class="opt" data-opt="' + n + '">' + n + "</button>").join("") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '<div id="exp" class="explain hidden"></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  area.querySelectorAll("[data-opt]").forEach((btn) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      btn.onclick = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (jogo.pick !== null) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  jogo.pick = btn.getAttribute("data-opt");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const ok = jogo.pick === item.c;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (ok) jogo.acertos++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    area.querySelectorAll(".opt").forEach((b) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            b.disabled = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (b.getAttribute("data-opt") === item.c) b.classList.add("ok");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!ok) btn.classList.add("bad");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const exp = $("exp");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            exp.classList.remove("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  exp.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "<p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (ok ? "Natureza correta." : "Esta conta é " + item.c + ".") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "</p>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<div class="row"><button class="btn" id="prox">Próxima</button></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $("prox").onclick = nextItem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function nextItem() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                jogo.i++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  jogo.pick = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (jogo.i >= jogo.m.itens.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const total = jogo.m.itens.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const acc = jogo.acertos / total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let stars = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (acc >= 0.7) stars = 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (acc >= 0.9) stars = 3;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const replay = (state.stars[jogo.m.id] || 0) >= 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const xp = Math.round(80 * (0.55 + 0.45 * acc) * (replay ? 0.25 : 1));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    state.xp += xp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        state.stars[jogo.m.id] = Math.max(state.stars[jogo.m.id] || 0, stars);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.answered += total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                state.correct += jogo.acertos;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    save(state);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $("jogo-kicker").textContent = "Missão concluída";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $("jogo-titulo").textContent = "Caderno encerrado";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("jogo-status").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jogo.acertos + " de " + total + " corretos · +" + xp + " XP · " + stars + " estrela(s)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $("jogo-area").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '<div class="row"><button class="btn" data-go="trilha">Voltar à trilha</button></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderJogo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $("form-capa").addEventListener("submit", (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            state.nome = $("nome").value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              state.turma = $("turma").value.trim() || "3º período";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                save(state);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  show("caderno");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.body.addEventListener("click", (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const go = e.target.closest("[data-go]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (go) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const dest = go.getAttribute("data-go");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if ((dest === "caderno" || dest === "trilha" || dest === "ranking") && !state.nome) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        show("capa");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      show(dest);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const play = e.target.closest("[data-play]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (play) start(play.getAttribute("data-play"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (state.nome) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $("nome").value = state.nome;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $("turma").value = state.turma;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  show("caderno");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    show("capa");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
